# Let me use a different approach - look for historical CPI data that might be in the resources
import os
import re

# Search for any CPI data in the available files
for root, dirs, files in os.walk('/app/resources'):
    for f in files:
        if f.endswith('.txt') or f.endswith('.json'):
            try:
                with open(os.path.join(root, f), 'r') as file:
                    content = file.read()
                    if 'CPI' in content or 'consumer price' in content.lower():
                        print(f"Found in {f}")
            except:
                pass

print("\nDone searching")
EOF
